-- VERIFY after migration 1 of 4: household
-- Run in the same SQL Editor immediately after 01_household.sql succeeded (before the next migration).
-- Read-only. Every row must show ok = true, and the last row must say ALL OK. If anything is false, STOP and tell the assistant; do not continue.
with c(check_name, expected, actual) as (values
  ('history row recorded', '1', (select count(*)::text from supabase_migrations.schema_migrations where name='household')::text),
  ('5 household tables have RLS', '5/5', (select count(*) filter (where rowsecurity)::text||'/'||count(*)::text from pg_tables where schemaname='public' and tablename in ('households','household_members','household_invites','household_meals','household_grocery_items'))::text),
  ('household policies (count : hash)', '10:fc286711671e3ce4f004d76fb8e449ed', (select count(*)::text||':'||md5(string_agg(tablename||policyname||cmd||array_to_string(roles,',')||coalesce(qual,'')||coalesce(with_check,''),'|' order by tablename,policyname)) from pg_policies where schemaname='public' and tablename in ('households','household_members','household_invites','household_meals','household_grocery_items'))::text),
  ('household column definitions (hash)', 'db406575850b3e3143a4be995a4289ef', (select md5(string_agg(t,'|' order by t)) from (select table_name||':'||string_agg(column_name||' '||data_type||' '||is_nullable||' '||coalesce(column_default,''),',' order by ordinal_position) t from information_schema.columns where table_schema='public' and table_name in ('households','household_members','household_invites','household_meals','household_grocery_items') group by table_name) x)::text),
  ('household constraints (count : hash)', '22:21e3aea979d57c9b0f9a6f177b650072', (select count(*)::text||':'||md5(string_agg(conrelid::regclass::text||conname||pg_get_constraintdef(c.oid),'|' order by conrelid::regclass::text,conname)) from pg_constraint c where connamespace='public'::regnamespace and conrelid::regclass::text in ('households','household_members','household_invites','household_meals','household_grocery_items'))::text),
  ('household indexes (count : hash)', '10:dbae91f14ba38c9d790b8029c28126eb', (select count(*)::text||':'||md5(string_agg(indexdef,'|' order by indexname)) from pg_indexes where schemaname='public' and tablename in ('households','household_members','household_invites','household_meals','household_grocery_items'))::text),
  ('5 public RPCs: definitions, empty search_path (count : hash)', '5:9f7c0c3a66c8b8c70f7fd3926c1e2cbf', (select count(*)::text||':'||md5(string_agg(proname||'('||pg_get_function_identity_arguments(p.oid)||')'||md5(prosrc)||coalesce(proconfig::text,''),'|' order by proname)) from pg_proc p where pronamespace='public'::regnamespace and proname in ('household_create','household_create_invite','household_join','household_leave','household_remove_member'))::text),
  ('3 app helper functions: definitions (count : hash)', '3:ff757717560dcc00d00783e1614e652c', (select count(*)::text||':'||md5(string_agg(proname||'('||pg_get_function_identity_arguments(p.oid)||')'||md5(prosrc)||coalesce(proconfig::text,''),'|' order by proname)) from pg_proc p where pronamespace='app'::regnamespace and proname in ('is_household_member','is_household_owner','household_after_member_delete'))::text),
  ('signed-in users can execute the 5 RPCs', '5', (select count(*)::text from pg_proc p where pronamespace='public'::regnamespace and proname in ('household_create','household_create_invite','household_join','household_leave','household_remove_member') and has_function_privilege('authenticated', p.oid, 'execute'))::text),
  ('anon can execute none of them', '0', (select count(*)::text from pg_proc p where pronamespace='public'::regnamespace and proname in ('household_create','household_create_invite','household_join','household_leave','household_remove_member') and has_function_privilege('anon', p.oid, 'execute'))::text),
  ('table grants for anon and authenticated (count : hash)', '7:9185d8e461ef0536e517b3917ac49706', (select count(*)::text||':'||md5(string_agg(table_name||privilege_type||grantee,'|' order by table_name,privilege_type,grantee)) from information_schema.role_table_grants where table_schema='public' and table_name in ('households','household_members','household_invites','household_meals','household_grocery_items') and grantee in ('anon','authenticated'))::text),
  ('column grants (count : hash)', '9:4d07ef7d0c55f22cc6613a07a70b350a', (select count(*)::text||':'||md5(string_agg(table_name||'.'||column_name||privilege_type||grantee,'|' order by table_name,column_name,privilege_type,grantee)) from information_schema.column_privileges where table_schema='public' and table_name in ('households','household_members','household_invites','household_meals','household_grocery_items') and grantee in ('anon','authenticated') and privilege_type in ('INSERT','UPDATE'))::text),
  ('member-delete trigger present', '1:household_members.household_members_after_delete', (select count(*)::text||':'||coalesce(string_agg(c.relname||'.'||t.tgname,',' order by c.relname),'') from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.relnamespace='public'::regnamespace and c.relname in ('households','household_members','household_invites','household_meals','household_grocery_items'))::text)
)
select check_name, expected, actual, (expected = actual) as ok from c
union all
select 'ALL OK', '', '', coalesce(bool_and(expected = actual), false) from c
order by 4, 1;
